import org.junit.jupiter.api.*;import org.springframework.boot.builder.SpringApplicationBuilder;import org.springframework.context.ConfigurableApplicationContext;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;import org.springframework.test.util.ReflectionTestUtils;import org.springframework.web.server.ResponseStatusException;
import com.trampolim.api.BackendApplication;import com.trampolim.api.radar.RadarBridge;import com.trampolim.api.security.TrailTokenService;import com.trampolim.api.geography.TerritorialCatalog;
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class ObservatoryPostgresTest {
 static final String SECRET="synthetic-observatory-secret-000000000000000000",ADMIN="observatory-admin@example.test";ConfigurableApplicationContext app;JdbcTemplate emp,cap,opp;EmploymentObservatory jobs;LearningObservatory learning;RadarBridge bridge;TerritorialCatalog geo;TrailTokenService tokens;String base,schema;final List<JdbcTemplate> roots=new ArrayList<>();final HttpClient http=HttpClient.newHttpClient();final com.fasterxml.jackson.databind.ObjectMapper json=new com.fasterxml.jackson.databind.ObjectMapper();final ZoneId zone=ZoneId.of("America/Sao_Paulo");YearMonth period;
 record Company(long id,long owner,String email){}record Course(long course,long module,long lesson,long assessment){}
 @BeforeAll void start(){schema="obs_test_"+UUID.randomUUID().toString().replace("-","");assertTrue(schema.matches("obs_test_[a-f0-9]{32}"));String[] urls={"jdbc:postgresql://localhost:5432/trampolim_db","jdbc:postgresql://localhost:5433/trampolim_empresas_db","jdbc:postgresql://localhost:5434/trampolim_capacita_db"},users={"root","trampolim_empresas","trampolim_capacita"},passwords={"root","dev_empresas_only","dev_capacita_only"};for(int i=0;i<3;i++){var db=new JdbcTemplate(new DriverManagerDataSource(urls[i],users[i],passwords[i]));db.execute("CREATE SCHEMA "+schema);roots.add(db);urls[i]+="?currentSchema="+schema;}app=new SpringApplicationBuilder(BackendApplication.class).run("--server.port=0","--spring.jpa.hibernate.ddl-auto=validate","--app.mail.enabled=false","--communications.worker-enabled=false","--operations.catalog-jobs-enabled=false","--career.observatory-capture-enabled=false","--future.poll-enabled=false","--passport.delivery-enabled=false","--app.admin.emails="+ADMIN,"--radar.bridge-secret="+SECRET,"--spring.datasource.url="+urls[0],"--spring.datasource.username="+users[0],"--spring.datasource.password="+passwords[0],"--trampolim.datasource.empresas.url="+urls[1],"--trampolim.datasource.empresas.username="+users[1],"--trampolim.datasource.empresas.password="+passwords[1],"--trampolim.datasource.capacita.url="+urls[2],"--trampolim.datasource.capacita.username="+users[2],"--trampolim.datasource.capacita.password="+passwords[2]);emp=app.getBean("empresasJdbcTemplate",JdbcTemplate.class);cap=app.getBean("capacitaJdbcTemplate",JdbcTemplate.class);opp=app.getBean("jdbcTemplate",JdbcTemplate.class);jobs=app.getBean(EmploymentObservatory.class);learning=app.getBean(LearningObservatory.class);bridge=app.getBean(RadarBridge.class);geo=app.getBean(TerritorialCatalog.class);tokens=app.getBean(TrailTokenService.class);base="http://127.0.0.1:"+app.getEnvironment().getRequiredProperty("local.server.port")+"/api";ReflectionTestUtils.setField(bridge,"base",base);opp.update("INSERT INTO app_users(email,password_hash,full_name,email_verified,account_type) VALUES (?,'synthetic','Administrador sintético',TRUE,'PERSON')",ADMIN);}
 @AfterAll void stop(){if(app!=null)app.close();if(schema!=null)for(var root:roots)root.execute("DROP SCHEMA "+schema+" CASCADE");}
 @BeforeEach void clean(){assertTrue(schema.matches("obs_test_[a-f0-9]{32}"));emp.execute("TRUNCATE company_users CASCADE");cap.execute("TRUNCATE student_users CASCADE");emp.update("DELETE FROM observatory_runs");cap.update("DELETE FROM observatory_runs");ReflectionTestUtils.setField(bridge,"base",base);period=YearMonth.now(zone).minusMonths(1);}
 Company company(){String email=UUID.randomUUID()+"@example.test";long owner=emp.queryForObject("INSERT INTO company_users(email,password_hash,full_name,email_verified,account_status) VALUES (?,'synthetic','Responsável sintético',TRUE,'ACTIVE') RETURNING id",Long.class,email);long id=emp.queryForObject("INSERT INTO companies(owner_user_id,legal_name,trade_name,cnpj,phone,industry,address,city,state,verification_status) VALUES (?,'Empresa sintética','Empresa sintética',?,'fixture','fixture','fixture','Irecê','BA','APPROVED') RETURNING id",Long.class,owner,String.format("%014d",Math.abs(UUID.randomUUID().getLeastSignificantBits()%100000000000000L)));emp.update("INSERT INTO company_members(company_id,user_id,role) VALUES (?,?,'OWNER')",id,owner);return new Company(id,owner,email);}
 Instant time(int day){return period.atDay(day).atTime(12,0).atZone(zone).toInstant();}java.sql.Timestamp ts(Instant at){return java.sql.Timestamp.from(at);}
 long vacancy(Company c,String city,String area){long id=emp.queryForObject("INSERT INTO company_listings(company_id,kind,title,area,description,requirements,location,modality,url,contact_email,publication_status,is_internship,payment_status,municipality_code,created_at) VALUES (?,'job','Vaga sintética',?,'Fixture','Fixture','Irecê','Presencial','https://example.test','private@example.test','PUBLISHED',FALSE,'NOT_PROCESSED',?,?) RETURNING id",Long.class,c.id(),area,city,ts(time(1).minus(Duration.ofDays(60))));emp.update("UPDATE career_listing_publications SET published_at=? WHERE listing_id=?",ts(time(4)),id);return id;}
 Map<String,Object> overview(String state,String city,boolean admin){return jobs.overview(period.toString(),period.toString(),state,"",city,UUID.randomUUID().toString(),admin);}
 void code(int expected,Runnable work){assertEquals(expected,assertThrows(ResponseStatusException.class,work::run).getStatusCode().value());}
 @Test void publicationUsesRecordedPublicationAndStockIsCurrentNotCreationCohort(){var c=company();long closed=vacancy(c,"2914604","Tecnologia"),active=vacancy(c,"2914604","Tecnologia");emp.update("UPDATE company_listings SET publication_status='CLOSED' WHERE id=?",closed);long untracked=vacancy(c,"2914604","Serviços");emp.update("DELETE FROM career_listing_publications WHERE listing_id=?",untracked);assertTrue(jobs.capture());var r=overview("BA","2914604",false);assertEquals(2L,((Number)r.get("registeredPublications")).longValue());var stock=(Map<?,?>)r.get("stocksAtCapture");assertEquals(2L,((Number)stock.get("active_listings")).longValue());assertEquals(1L,((Number)stock.get("active_without_publication_marker")).longValue());assertEquals(1L,((Number)r.get("participatingCompanies")).longValue());assertEquals("MUNICIPAL_DATA_UNAVAILABLE",((Map<?,?>)r.get("learning")).get("status"));assertFalse(r.toString().contains("private@example.test"));emp.update("UPDATE company_listings SET publication_status='CLOSED' WHERE id=?",active);assertEquals(2L,((Number)((Map<?,?>)overview("BA","2914604",false).get("stocksAtCapture")).get("active_listings")).longValue());assertTrue(jobs.capture());assertEquals(1L,((Number)((Map<?,?>)overview("BA","2914604",false).get("stocksAtCapture")).get("active_listings")).longValue());}
 @Test void geographyUsesOfficialCodesAndDistinctCompaniesAreNotSummedAcrossCities(){var c=company();String lapao=geo.search("Lapão","BA",50).stream().filter(x->x.name().equals("Lapão")).findFirst().orElseThrow().code();vacancy(c,"2914604","Comércio");vacancy(c,lapao,"Comércio");vacancy(c,"9999999","Serviços");String sp=geo.search("São Paulo","SP",50).stream().filter(x->x.name().equals("São Paulo")).findFirst().orElseThrow().code();vacancy(c,sp,"Tecnologia");jobs.capture();assertEquals(1L,((Number)overview("BA","",false).get("participatingCompanies")).longValue());assertEquals(3L,((Number)overview("BA","",false).get("registeredPublications")).longValue());assertEquals(1L,((Number)overview("SP",sp,false).get("registeredPublications")).longValue());var distribution=jobs.distribution(period.toString(),period.toString(),"BA","","","municipality",0,1,"fixture");assertTrue((Boolean)distribution.get("hasMore"));code(400,()->overview("SP","2914604",false));code(400,()->overview("BA","0000000",false));}
 @Test void unpaidInternshipsAreExcludedAndFailedCapturePreservesCommittedGeneration(){var c=company();long job=vacancy(c,"2914604","Saúde");emp.update("UPDATE company_listings SET is_internship=TRUE,payment_status='PENDING' WHERE id=?",job);jobs.capture();assertEquals(0L,((Number)overview("BA","2914604",false).get("registeredPublications")).longValue());emp.update("UPDATE company_listings SET payment_status='PAID' WHERE id=?",job);jobs.capture();assertEquals(1L,((Number)overview("BA","2914604",false).get("registeredPublications")).longValue());emp.execute("ALTER TABLE observatory_vacancy_cells ADD CONSTRAINT synthetic_failure CHECK(published<0) NOT VALID");try{assertThrows(org.springframework.dao.DataAccessException.class,()->jobs.capture());assertEquals(1L,((Number)overview("BA","2914604",false).get("registeredPublications")).longValue());}finally{emp.execute("ALTER TABLE observatory_vacancy_cells DROP CONSTRAINT synthetic_failure");}}
 long application(long job,String person){return emp.queryForObject("INSERT INTO company_applications(listing_id,candidate_name,candidate_email,created_at) VALUES (?,'Pessoa sintética',?,?) RETURNING id",Long.class,job,person,ts(time(5)));}
 void outcome(long app){emp.update("INSERT INTO company_selection_outcomes(id,application_id,interview_at,interview_held,hire_date,candidate_confirmed_at,public_metrics_consent,request_key,request_hash) VALUES (?,?,?,TRUE,?,?,TRUE,?,?)",UUID.randomUUID(),app,ts(time(6)),period.atDay(7),ts(time(8)),UUID.randomUUID(),"a".repeat(64));}
 Map<?,?> metric(Map<String,Object> result,String name){var recruitment=(Map<?,?>)result.get("recruitment");var items=(List<?>)recruitment.get("items");return (Map<?,?>)((Map<?,?>)items.getFirst()).get(name);}
 @Test void personalMetricsRequireDistinctContributorsAndThreeCompaniesAndNoPrivateDataIsPublic(){var companies=List.of(company(),company(),company());var listings=companies.stream().map(c->vacancy(c,"2914604","Serviços")).toList();for(int i=0;i<9;i++)outcome(application(listings.get(i%3),"private-"+i+"@example.test"));for(long listing:listings.subList(1,3))outcome(application(listing,"private-0@example.test"));jobs.capture();assertEquals(false,metric(overview("BA","",false),"CONFIRMED_HIRES").get("available"));outcome(application(listings.getFirst(),"private-9@example.test"));jobs.capture();var pub=overview("BA","",false);assertEquals(true,metric(pub,"CONFIRMED_HIRES").get("available"));assertFalse(metric(pub,"CONFIRMED_HIRES").containsKey("value"));assertFalse(pub.toString().contains("private-0@example.test"));assertFalse(pub.toString().contains("APPLICATIONS"));assertEquals(true,metric(overview("BA","",true),"APPLICATIONS").get("available"));assertEquals("MUNICIPAL_DATA_NOT_DISCLOSED",((Map<?,?>)overview("BA","2914604",false).get("recruitment")).get("status"));emp.update("UPDATE company_selection_outcomes SET public_metrics_consent=FALSE WHERE application_id=(SELECT min(id) FROM company_applications)");assertEquals("INVALIDATED",overview("BA","",false).get("status"));}
 @Test void peopleFromOneCompanyAreNotPublishedEvenWhenCountIsLarge(){var c=company();long job=vacancy(c,"2914604","Serviços");for(int i=0;i<12;i++)outcome(application(job,"single-"+i+"@example.test"));jobs.capture();assertEquals(false,metric(overview("BA","",false),"CONFIRMED_HIRES").get("available"));}
 long learner(){return cap.queryForObject("INSERT INTO student_users(email,password_hash,full_name,education_stage,email_verified,account_status,terms_accepted_at) VALUES (?,'synthetic','Aluno sintético','HIGH_SCHOOL',TRUE,'ACTIVE',CURRENT_TIMESTAMP) RETURNING id",Long.class,UUID.randomUUID()+"@example.test");}
 Course course(){long teacher=learner();long c=cap.queryForObject("INSERT INTO learning_courses(teacher_id,title,description,category,status) VALUES (?,'Curso sintético','Fixture','Teste','PUBLISHED') RETURNING id",Long.class,teacher);long s=cap.queryForObject("INSERT INTO learning_subjects(course_id,title) VALUES (?,'Disciplina sintética') RETURNING id",Long.class,c);long m=cap.queryForObject("INSERT INTO learning_modules(subject_id,title) VALUES (?,'Módulo sintético') RETURNING id",Long.class,s);long l=cap.queryForObject("INSERT INTO learning_lessons(module_id,title,status,validation_status,media_key,duration_seconds) VALUES (?,'Aula sintética','PUBLISHED','READY',?,180) RETURNING id",Long.class,m,UUID.randomUUID());long a=cap.queryForObject("INSERT INTO learning_assessments(course_id,title,status,draft) VALUES (?,'Prova sintética','DRAFT','{}') RETURNING id",Long.class,c);long v=cap.queryForObject("INSERT INTO learning_assessment_versions(assessment_id,version_number,definition) VALUES (?,1,jsonb_build_object('requiredForCompletion',TRUE)) RETURNING id",Long.class,a);cap.update("UPDATE learning_assessments SET status='PUBLISHED',current_version_id=? WHERE id=?",v,a);return new Course(c,m,l,a);}
 void consent(long student){cap.update("INSERT INTO learning_observatory_consents(student_id,region_code,consent_at) VALUES (?,'BA',?)",student,ts(time(1)));}
 UUID pass(long student,Course c){long version=cap.queryForObject("SELECT current_version_id FROM learning_assessments WHERE id=?",Long.class,c.assessment());UUID id=UUID.randomUUID();cap.update("INSERT INTO learning_assessment_attempts(id,assessment_id,version_id,student_id,attempt_number,status,answers,submission_key,earned_points,total_points,score_percent,passed,criteria,submitted_at) VALUES (?,?,?,?,1,'SUBMITTED','{}',?,80,100,80,TRUE,'{}',?)",id,c.assessment(),version,student,UUID.randomUUID(),ts(time(10)));return id;}
 void award(long student,Course c,UUID attempt){cap.update("INSERT INTO learning_competency_awards(id,student_id,assessment_id,attempt_id,competency_key,name,description,course_id,module_id,course_title,module_title,teacher_name,score_percent,criterion,awarded_at) VALUES (?,?,?,?,?,'Competência sintética','Fixture',?,?,'Curso sintético','Módulo sintético','Professor sintético',80,'Critério sintético',?)",UUID.randomUUID(),student,c.assessment(),attempt,UUID.randomUUID(),c.course(),c.module(),ts(time(11)));}
 Map<?,?> educationMetric(String name){var r=learning.indicators(period.toString(),period.toString(),"BA");return (Map<?,?>)((Map<?,?>)((List<?>)r.get("items")).getFirst()).get(name);}
 @Test void learningRequiresEveryLessonAndAssessmentAndContributorPrivacy(){var c=course();var learners=new ArrayList<Long>();for(int i=0;i<10;i++){long student=learner();learners.add(student);consent(student);cap.update("INSERT INTO learning_lesson_progress(student_id,lesson_id,position_seconds,watched_seconds,completed_at) VALUES (?,?,180,180,?)",student,c.lesson(),ts(time(9)));if(i<9){UUID attempt=pass(student,c);award(student,c,attempt);}}learning.capture();assertEquals(false,educationMetric("COURSE_COMPLETIONS").get("available"));assertEquals(false,educationMetric("VERIFIED_AWARDS").get("available"));UUID last=pass(learners.getLast(),c);award(learners.getLast(),c,last);learning.capture();assertEquals(true,educationMetric("COURSE_COMPLETIONS").get("available"));assertEquals(10L,educationMetric("VERIFIED_AWARDS").get("lowerBound"));cap.update("DELETE FROM learning_observatory_consents WHERE student_id=?",learners.getLast());assertEquals("INVALIDATED",learning.indicators(period.toString(),period.toString(),"BA").get("status"));learning.capture();assertEquals(false,educationMetric("COURSE_COMPLETIONS").get("available"));}
 @Test void missingStaleAndRemoteFailureAreNotReportedAsZero(){assertEquals("NOT_CAPTURED",overview("BA","",false).get("status"));vacancy(company(),"2914604","Tecnologia");jobs.capture();ReflectionTestUtils.setField(bridge,"base","http://127.0.0.1:1/api");var r=overview("BA","",false);assertEquals("READY",r.get("status"));assertEquals("UNAVAILABLE",((Map<?,?>)r.get("learning")).get("status"));emp.update("UPDATE observatory_runs SET observed_at=CURRENT_TIMESTAMP-INTERVAL '3 hours'");var stale=overview("BA","",false);assertEquals("STALE",stale.get("status"));assertFalse(stale.containsKey("registeredPublications"));assertEquals(1,emp.queryForObject("SELECT count(*) FROM observatory_runs",Integer.class));code(400,()->jobs.overview("2026-02-31",period.toString(),"BA","","","fixture",false));}
 HttpResponse<String> call(String method,String path,Object body,String token,String key)throws Exception{var b=HttpRequest.newBuilder(URI.create(base+path));if(token!=null)b.header("Authorization","Bearer "+token);if(key!=null)b.header("X-Trampolim-Bridge",key);b.header("Content-Type","application/json");b.method(method,body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(json.writeValueAsString(body)));return http.send(b.build(),HttpResponse.BodyHandlers.ofString());}
 @Test void apiProtectsOperationalMetricsAndInternalLearningSource()throws Exception{vacancy(company(),"2914604","Tecnologia");jobs.capture();learning.capture();String query="?fromMonth="+period+"&toMonth="+period+"&state=BA";assertEquals(200,call("GET","/public/career/observatory/indicators"+query,null,null,null).statusCode());assertTrue(Set.of(401,403).contains(call("GET","/admin/observatory/indicators"+query,null,null,null).statusCode()));long uid=opp.queryForObject("SELECT id FROM app_users WHERE email=?",Long.class,ADMIN);String admin=tokens.issue(TrailTokenService.Trail.OPORTUNIDADES,ADMIN,uid,0);assertEquals(200,call("GET","/admin/observatory/indicators"+query,null,admin,null).statusCode());var c=company();String corporate=tokens.issue(TrailTokenService.Trail.EMPRESAS,c.email(),c.owner(),0);assertTrue(Set.of(401,403).contains(call("GET","/admin/observatory/indicators"+query,null,corporate,null).statusCode()));var body=new ObservatoryController.LearningQuery(period.toString(),period.toString(),"BA");assertEquals(401,call("POST","/integrations/career/observatory/v2/learning",body,null,null).statusCode());assertEquals(200,call("POST","/integrations/career/observatory/v2/learning",body,null,SECRET).statusCode());assertEquals(400,call("GET","/public/career/observatory/distribution"+query+"&dimension=municipality&limit=51",null,null,null).statusCode());}

 @Test void preparedReadsDoNotQueryOperationalTablesAndExposeAnActualPlan(){vacancy(company(),"2914604","Tecnologia");jobs.capture();String plan=emp.queryForObject("EXPLAIN (ANALYZE,BUFFERS,FORMAT JSON) SELECT month,sum(published) FROM observatory_vacancy_cells WHERE run_id=(SELECT id FROM observatory_runs ORDER BY observed_at DESC LIMIT 1) AND state='BA' GROUP BY month",String.class);assertTrue(plan.contains("observatory_vacancy_cells"));assertFalse(plan.contains("company_listings"));System.out.println("OBSERVATORY_PREPARED_QUERY_PLAN "+plan.replace(System.lineSeparator()," "));emp.execute("ALTER TABLE company_listings RENAME TO synthetic_operational_unavailable");try{for(int i=0;i<5;i++)assertEquals(1L,((Number)overview("BA","2914604",false).get("registeredPublications")).longValue());}finally{emp.execute("ALTER TABLE synthetic_operational_unavailable RENAME TO company_listings");}}
}
